import gurobipy as gp
from gurobipy import GRB
shelves = []
capacity = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        rid = rec['values']['resource_id']
        shelves.append(rid)
        capacity[rid] = int(rec['values']['resource_capacity'])
products = []
item_value = {}
resource_requirement = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pid = rec['values']['item_name']
        products.append(pid)
        item_value[pid] = int(rec['values']['item_value'])
        resource_requirement[pid] = int(rec['values']['resource_requirement'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('No shelves or products found in LEGACY_RECORDS')
for rid in shelves:
    if rid not in capacity:
        raise ValueError(f'Missing capacity for shelf {rid}')
for pid in products:
    if pid not in item_value or pid not in resource_requirement:
        raise ValueError(f'Missing value or requirement for product {pid}')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[pid] * x[rid, pid] for rid in shelves for pid in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((resource_requirement[pid] * x[rid, pid] for pid in products)) <= capacity[rid] for rid in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')